(()=>{const $=id=>document.getElementById(id),E=window.ScheduleEngine,M=window.OverlapModel,D=window.SCHEDULE_DATA,days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];let day=0;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const time=n=>{n=(n%1440+1440)%1440;const h=Math.floor(n/60);return `${h%12||12}:${String(n%60).padStart(2,'0')} ${h<12?'am':'pm'}`};
const categories={'Benefits':['Benefits office support','SNAP office support','Medicaid office support','Family Services recertification','Specialized benefits support'],'ID & records':['IDNYC enrollment','Marriage license','Non-criminal fingerprints','Driver license, ID and vehicle transactions','Driver license and ID transactions (verify current service)'],'Family & school':['School enrollment help','Child support services','Family Justice Center support'],'Housing & work':['Homebase housing support','Workforce1 career help'],'Health':['Sexual health clinic','Express STI testing','TB clinic visit'],'Other errands':['Finance counter service','Cash bail / court & trust counter','Building and property customer service','Administrative summons hearing','Business licensing appointment','Pay DCWP fines and fees in person','Small-business and street-vendor application support']};
$('category').innerHTML=Object.keys(categories).map(x=>`<option>${esc(x)}</option>`).join('');
function services(){$('service').innerHTML=categories[$('category').value].map(x=>`<option>${esc(x)}</option>`).join('');offices();}
function rows(){return D.records.filter(r=>r.channel==='in_person'&&r.status!=='closed'&&r.service===$('service').value);}
function offices(){$('office').innerHTML=rows().map(r=>`<option value="${esc(r.id)}">${esc(r.name)} · ${esc(r.borough)}</option>`).join('');render();}
function settings(){const s={days:[0,1,2,3,4]};for(const id of ['start','end','sleepStart','sleepEnd','careStart','careEnd','otherStart','otherEnd'])s[id]=$(id).value;for(const id of ['travel','commute','duration','wait'])s[id]=+$(id).value;for(const id of ['care','other'])s[id]=$(id).checked;return s;}
function spans(xs,cls,label){return xs.map(([a,b])=>`<span class="block ${cls}" style="left:${(a-day*1440)/14.4}%;width:${(b-a)/14.4}%" title="${label}: ${time(a)}–${time(b)}">${b-a>=85?label:''}</span>`).join('');}
function render(){if([...document.querySelectorAll('input[type=time]')].some(i=>!i.value))return;const s=settings();$('careTimes').hidden=!s.care;$('otherTimes').hidden=!s.other;$('assumptionSummary').textContent=`${s.travel} min travel · ${s.duration} min visit${s.wait?' + '+s.wait+' min wait':''}`;$('days').innerHTML=days.map((d,i)=>`<button data-day="${i}" class="${i===day?'active':''}" aria-pressed="${i===day}">${d}</button>`).join('');const all=rows(),r=all.find(r=>r.id===$('office').value);if(!r)return;const p=M.model(r,s,day);const n=all.map(r=>({r,p:M.model(r,s,day)})),known=n.filter(x=>x.p.kind!=='unknown'),fits=known.filter(x=>x.p.kind==='fits');
$('person').innerHTML='<span class="base free">Free time</span>'+spans(p.sleep,'sleep','Sleep')+spans(p.commute,'commute','Commute')+spans(p.work,'work','Work')+spans(p.life,'care','Care / life');$('person').setAttribute('aria-label',`Your ${days[day]}: `+[['work',p.work],['commute',p.commute],['sleep',p.sleep],['care or life',p.life]].map(([label,xs])=>label+' '+xs.map(([a,b])=>time(a)+' to '+time(b)).join(', ')).join('; '));
$('officeHours').innerHTML=p.kind==='unknown'?'<span class="base unknown">Hours unknown</span>':'<span class="base closed">Closed</span>'+spans(p.office,'open','Open');$('officeHours').setAttribute('aria-label',p.kind==='unknown'?'Hours unknown':p.office.length?'Office open '+p.office.map(([a,b])=>time(a)+' to '+time(b)).join(', '):'No regular opening hours this day');
$('overlap').innerHTML=p.kind==='unknown'?'<span class="base unknown">Not enough information</span>':p.windows.length?'<span class="base closed"></span>'+spans(p.windows,'possible','A possible visit'):'<span class="base no-fit">No usable window</span>';$('overlap').setAttribute('aria-label',p.kind==='unknown'?'Cannot assess':p.windows.length?'Possible visit periods '+p.windows.map(([a,b])=>time(a)+' to '+time(b)).join(', '):'No visit fits your current schedule, including travel');
window.Booking.render(r,s,day,p);
const noLife=M.model(r,{...s,care:false,other:false},day);const reason=p.kind==='unknown'?'This office has no verified regular schedule.':p.kind==='fits'?`Leave at ${time(p.first-s.travel)}. Visit at ${time(p.first)}. Return at ${time(p.first+s.duration+s.wait+s.travel)}.`:!p.office.length?'No regular opening hours are listed for this day.':noLife.kind==='fits'?'Your care or other commitments remove the remaining window.':'A full visit and travel don’t fit around your work, commute and sleep.';
$('finding').innerHTML=`<div class="verdict ${p.kind}"><div><p class="eyebrow">${esc(r.name)} · ${days[day]}</p><h2>${p.kind==='fits'?'There’s a possible window.':p.kind==='unknown'?'We can’t tell yet.':'No window without changing your day.'}</h2><p>${esc(reason)}</p></div><div class="count"><strong>${fits.length}<span> / ${known.length}</span></strong><p>office schedules fit<br>this service · this day</p></div></div><p class="micro">${n.length-known.length} hours unknown, excluded · estimated travel · ${s.wait?s.wait+' min estimated waiting':'waiting not included'} · regular hours only</p>`;
$('alternatives').innerHTML=`<details class="remote" ${p.kind==='conflict'?'open':''}><summary>Can I skip the trip?</summary><p>${esc(r.remoteAlternative||'No remote alternative verified for this record.')}</p><p>${esc(r.appointment||'')}</p><a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">Check the official instructions ↗</a>${r.exceptionsText?'<p class="micro">'+esc(r.exceptionsText)+'</p>':''}</details><details><summary>Compare ${all.length} offices</summary><div class="office-list">${n.map(x=>`<button data-office="${esc(x.r.id)}"><span>${esc(x.r.name)}<small>${esc(x.r.borough)}</small></span><strong>${x.p.kind==='fits'?'Possible window':x.p.kind==='unknown'?'Hours unknown':'No window'}</strong></button>`).join('')}</div></details>`;
}
$('category').onchange=services;$('service').onchange=offices;$('office').onchange=render;$('days').onclick=e=>{const b=e.target.closest('[data-day]');if(b){day=+b.dataset.day;render();}};$('alternatives').onclick=e=>{const b=e.target.closest('[data-office]');if(b){$('office').value=b.dataset.office;render();}};
$('workChoices').onclick=e=>{const b=e.target.closest('[data-work]');if(!b)return;const p={day:['09:00','17:00','23:00','07:00'],shift:['07:00','15:00','22:00','06:00'],night:['22:00','06:00','07:00','15:00']}[b.dataset.work];['start','end','sleepStart','sleepEnd'].forEach((id,i)=>$(id).value=p[i]);document.querySelectorAll('[data-work]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});render();};
for(const input of document.querySelectorAll('input, .assumptions select'))input.addEventListener('change',render);for(const id of ['start','end'])$(id).addEventListener('change',()=>document.querySelectorAll('[data-work]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');}));$('snapshot').textContent=`Source snapshot · ${D.checkedDate}`;services();})();
